const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const SKILLS=['Listening','Speaking','Reading','Writing','Vocabulary','Intercultural'];
const ZONES=[['✒','Aksara Nusantara','Script recognition, manuscript literacy, heritage families.','Aksara Studio','studio'],['〰','Suara & Cerita','Oral stories, legends, listening, and pronunciation.','Voice Atlas','voice'],['✺','Diversity in Communication','Language awareness, empathy, and intercultural dialogue.','Skills Lab','skills'],['◎','English for the World','Vocabulary, reading, speaking, writing, and global communication.','Integrated Skills','skills'],['AI','AI & Future Learning','Offline ethical feedback, adaptive prompts, and future-ready skills.','AI Tutor','ai'],['✦','Nusantara English Futures','Creative projects, QR discovery, dossier, and innovation.','QR + Dossier','qr']];
let state={selected:1,region:'All',skill:'Listening',progress:{},custom:{},materials:{},recordings:{},unlocked:false};
let recorder=null, recChunks=[];
function load(){try{state=Object.assign(state,JSON.parse(localStorage.getItem('aksantaraStateV3')||'{}'))}catch(e){} if(location.hash.startsWith('#province-')){const n=+location.hash.replace('#province-',''); if(n) state.selected=n;}}
function save(){localStorage.setItem('aksantaraStateV3',JSON.stringify(state));}
function baseProv(n=state.selected){return PROVINCES.find(p=>p.n==n)||PROVINCES[0]}
function p(n=state.selected){const b=baseProv(n), c=state.custom[b.n]||{}; return {...b,...c, samples:c.samples||b.samples}}
function samples(){return p().samples||[]}
function toast(t){const el=$('#toast'); el.textContent=t; el.classList.add('show'); setTimeout(()=>el.classList.remove('show'),1600)}
function go(id){const el=document.getElementById(id); if(el) el.scrollIntoView({behavior:'smooth'}); $$('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.go===id)); $('#nav').classList.remove('open')}
function setProvince(n){state.selected=+n; location.hash='province-'+n; save(); updateAll();}
function renderOptions(){const opts=PROVINCES.map(pr=>`<option value="${pr.n}">${pr.n}. ${pr.name} — ${p(pr.n).aksara}</option>`).join(''); ['studioSelect','voiceSelect','qrSelect','adminSelect'].forEach(id=>{const el=$('#'+id); if(el){el.innerHTML=opts; el.value=state.selected}})}
function renderZones(){ $('#zoneGrid').innerHTML=ZONES.map((z,i)=>`<article class="zone-card"><div class="zone-icon">${z[0]}</div><small>${i+1}</small><b>${z[1]}</b><p>${z[2]}</p><button class="btn" data-go="${z[4]}">${z[3]}</button></article>`).join(''); }
function renderFilters(){const regs=['All','Sumatra','Java','Kalimantan','Sulawesi','Bali & Nusa Tenggara','Maluku','Papua']; $('#filters').innerHTML=regs.map(r=>`<button class="option filter ${state.region===r?'active':''}" data-region="${r}">${r}</button>`).join('')}
function filtered(){const q=($('#search')?.value||'').toLowerCase(); return PROVINCES.filter(b=>{const pr=p(b.n); const regionOk=state.region==='All'||pr.region===state.region; const qOk=!q||[pr.name,pr.aksara,pr.wisdom,pr.story,pr.region].join(' ').toLowerCase().includes(q); return regionOk&&qOk})}
function renderCards(){ $('#cards').innerHTML=filtered().map(b=>{const pr=p(b.n); return `<button class="province-card ${pr.n===state.selected?'active':''}" data-prov="${pr.n}"><h4>${pr.name}</h4><p>${pr.aksara} • ${pr.wisdom}</p></button>`}).join('') }
function renderMap(){renderCards(); const st=$('.map-stage'); const img=$('#mapImg'); const iw=img.clientWidth||st.clientWidth, ih=img.clientHeight||st.clientHeight; $('#hotspotLayer').innerHTML=PROVINCES.map(b=>{const pr=p(b.n); return `<button class="hotspot ${pr.n===state.selected?'active':''}" style="left:${pr.x}%;top:${pr.y}%" data-prov="${pr.n}" title="${pr.name}">${pr.n}</button>`}).join(''); const pr=p(); $('#selectedChips').innerHTML=`<button class="chip" data-prov="${pr.n}">Province ${pr.n}: ${pr.name}</button><span class="chip">${pr.region}</span><span class="chip">${pr.aksara}</span><span class="chip">${pr.wisdom}</span><button class="chip" data-go="studio">Aksara Studio linked</button><button class="chip" data-go="skills">Skills linked</button><button class="chip" data-go="voice">Voice linked</button><button class="chip" data-go="qr">QR linked</button>`;}
function updateStudio(){const pr=p(); $('#studioSelect').value=pr.n; $('#studioTitle').textContent=`${pr.name} — ${pr.aksara}`; $('#studioDesc').innerHTML=`This studio promotes <b>${pr.aksara}</b> as a gateway to ${pr.wisdom}. Click any sample below to write it into the studio. Each sample can be copied, traced, and transformed into English–Indonesian learning sentences.`; $('#sampleGrid').innerHTML=samples().map((s,i)=>`<button class="sample" data-sample="${i}" title="${s.meaning}">${s.ch}</button>`).join('');}
function applySample(i){const s=samples()[i], pr=p(); if(!s)return; const unit=document.createElement('span'); unit.className='unit'; unit.contentEditable='false'; unit.dataset.i=i; unit.textContent=s.ch; $('#workspace').appendChild(unit); $('#workspace').appendChild(document.createTextNode(' ')); $('#translationBox').innerHTML=`<b>${s.ch}</b> — ${s.meaning}<br><b>EN:</b> ${s.en}<br><b>ID:</b> ${s.id}`; $$('.sample').forEach(x=>x.classList.remove('active')); const btn=$(`.sample[data-sample="${i}"]`); if(btn) btn.classList.add('active'); toast('Aksara sample inserted.');}
function translateWorkspace(){const pr=p(); const units=$$('#workspace .unit'); if(units.length){const chars=units.map(u=>u.textContent.trim()).join(' '); const meanings=units.map(u=>samples()[+u.dataset.i]?.meaning).filter(Boolean); $('#translationBox').innerHTML=`<b>Written Aksara:</b> ${chars}<br><b>EN:</b> The selected ${pr.aksara} samples represent ${pr.wisdom}: ${meanings.join('; ')}.<br><b>ID:</b> Sampel ${pr.aksara} yang dipilih merepresentasikan ${pr.wisdom}: ${meanings.join('; ')}.`;} else {const txt=$('#workspace').textContent.trim(); $('#translationBox').innerHTML=txt?`<b>Typed Aksara:</b> ${txt}<br><b>EN:</b> This typed script is interpreted within ${pr.name}'s ${pr.aksara} learning context.<br><b>ID:</b> Aksara yang diketik ditafsirkan dalam konteks pembelajaran ${pr.aksara} dari ${pr.name}.`:'<b>Meaning / Translation:</b><br>Select or type aksara samples. Translation results will appear here.';} }
function updateSkills(){const pr=p(); $('#skillTabs').innerHTML=SKILLS.map(s=>`<button class="option ${state.skill===s?'active':''}" data-skill="${s}">${s}</button>`).join(''); const done=SKILLS.filter(s=>state.progress[pr.n+'-'+s]).length; $('#skillProvince').innerHTML=`<b>${pr.name} — ${pr.aksara}</b><br>${pr.wisdom}`; $('#skillProgress').style.width=(done/SKILLS.length*100)+'%'; $('#skillDone').textContent=`${done} of ${SKILLS.length} tasks completed`; const doneSkill=state.progress[pr.n+'-'+state.skill]; let h=`<h3>${state.skill}: ${pr.story}</h3>`; if(state.skill==='Listening')h+=`<p>Listen to the model sentence, then choose the best meaning.</p><button class="btn primary" id="playListen">Play Listening Text</button><div class="task-options"><button data-answer="1">The province teaches cultural communication through local wisdom.</button><button data-answer="0">The province rejects English learning.</button><button data-answer="0">The province has no oral tradition.</button></div>`; if(state.skill==='Speaking')h+=`<p>Prepare a 60-second spoken explanation of ${pr.aksara} and ${pr.wisdom} for international visitors.</p><button class="btn primary" data-complete="1">Mark Speaking Practice Complete</button>`; if(state.skill==='Reading')h+=`<p><b>Reading passage:</b> ${pr.story} represents ${pr.wisdom}. Learners examine how local scripts and values can become sources for global English communication.</p><button class="btn primary" data-complete="1">Complete Reading Analysis</button>`; if(state.skill==='Writing')h+=`<p>Write an academic paragraph connecting ${pr.name}, ${pr.aksara}, and ethical AI-supported English learning.</p><textarea id="writeText" placeholder="Write your paragraph here..."></textarea><button class="btn primary" data-complete="1">Save Writing Task</button>`; if(state.skill==='Vocabulary')h+=`<p><b>Vocabulary bank:</b> heritage, intelligibility, interculturality, archive, manuscript, transformation, dialogue, local wisdom, ethics, identity.</p><button class="btn primary" data-complete="1">Save Vocabulary Task</button>`; if(state.skill==='Intercultural')h+=`<p>Question: How can ${pr.name} share ${pr.wisdom} with international audiences without losing local identity?</p><textarea placeholder="My intercultural answer..."></textarea><button class="btn primary" data-complete="1">Save Reflection</button>`; if(doneSkill) h+=`<p class="ok">Completed.</p>`; $('#taskContent').innerHTML=h; const pl=$('#playListen'); if(pl) pl.onclick=()=>speak(`${pr.name} connects ${pr.aksara} and ${pr.wisdom} with intelligible English communication.`);}
function updateVoice(){const pr=p(); $('#voiceSelect').value=pr.n; $('#voiceTitle').textContent=`${pr.name} Voice Atlas`; $('#voiceSentence').innerHTML=`Model sentence: <b>${pr.name}</b> connects ${pr.aksara} and ${pr.wisdom} with intelligible English communication.`; $('#pronFocus').textContent=pr.focus; $('#voiceStatus').textContent=state.recordings[pr.n]?'Saved local accent sample available.':'Ready for model line or local accent recording.'; $('#voiceScoreBar').style.width='0%'; $('#voiceScore').textContent='Ready'; $('#voiceWave').innerHTML=Array.from({length:60},(_,i)=>`<span class="bar" style="animation-delay:${(i%12)*.04}s"></span>`).join('')}
function updateAI(){const pr=p(); $('#chat').innerHTML=`<div><b>Welcome to AKSANTARA AI.</b><br>Selected province: <b>${pr.name}</b>.<br>Aksara: <b>${pr.aksara}</b>. Local wisdom: <b>${pr.wisdom}</b>.</div>`; $('#promptButtons').innerHTML=['Create a speaking prompt','Explain the local wisdom','Give five vocabulary words','Make a writing model','Translate the concept into Indonesian','Create assessment rubric'].map(x=>`<button class="option prompt" data-prompt="${x}">${x}</button>`).join('')}
function aiAnswer(q){const pr=p(); const qq=q.toLowerCase(); if(qq.includes('vocab'))return `<div class="info"><b>Vocabulary:</b> heritage, script, wisdom, oral tradition, identity, intelligibility, dialogue, ethics, archive, transformation.</div>`; if(qq.includes('rubric'))return `<div class="info"><b>Rubric:</b> 1) cultural accuracy, 2) clarity of English, 3) intelligibility, 4) intercultural respect, 5) connection to ${pr.aksara}.</div>`; if(qq.includes('indonesian')||qq.includes('translate'))return `<div class="info"><b>ID:</b> ${pr.name} menggunakan ${pr.aksara} dan ${pr.wisdom} sebagai dasar pembelajaran bahasa Inggris yang etis dan berwawasan global.</div>`; return `<div class="info"><b>Response:</b> For ${pr.name}, ${pr.aksara} represents ${pr.wisdom}. Use ${pr.story.toLowerCase()} as the topic for an intelligible English explanation to international audiences.</div>`}
function updateQR(){const pr=p(); $('#qrSelect').value=pr.n; $('#qrProvince').textContent=`${pr.name} • ${pr.aksara}`; $('#qrImg').src=`assets/qr/${String(pr.n).padStart(2,'0')}.png`; $('#qrCaption').textContent=`${pr.wisdom}. ${pr.story}. Voice focus: ${pr.focus}.`; $('#qrDetails').innerHTML=`<button class="seedInfo" data-go="studio"><b>Open Aksara Studio:</b> ${pr.aksara}</button><button class="seedInfo" data-go="skills"><b>Open Skills Lab:</b> ${pr.wisdom}</button><button class="seedInfo" data-go="voice"><b>Open Voice Atlas:</b> ${pr.focus}</button><button class="seedInfo" data-go="ai"><b>Open AI Tutor:</b> ${pr.story}</button><div class="seedInfo"><b>QR content:</b> Province ${pr.n}, ${pr.name}, ${pr.aksara}, ${pr.wisdom}, and learning mission.</div>`}
function updateAdmin(){const pr=p(); $('#adminSelect').value=pr.n; $('#adminProvince').textContent=pr.name; $('#adminWisdom').value=pr.wisdom; $('#adminStory').value=pr.story; $('#adminFocus').value=pr.focus; const done=SKILLS.filter(s=>state.progress[pr.n+'-'+s]).length; $('#adminCompleted').textContent=done+'/'+(SKILLS.length+5); renderMaterials();}
function renderMaterials(){const pr=p(); const list=(state.materials[pr.n]||[]); $('#materialList').innerHTML=list.map((m,i)=>`<div class="material-item"><b>${m.title}</b><p>${m.body}</p><button class="btn" data-remove-material="${i}">Remove</button></div>`).join('') || '<p>No custom materials yet.</p>'}
function updateAll(){renderOptions();renderFilters();renderMap();updateStudio();updateSkills();updateVoice();updateAI();updateQR();updateAdmin();}
function speak(text){try{speechSynthesis.cancel(); const u=new SpeechSynthesisUtterance(text); u.lang='en-US'; u.rate=.88; u.pitch=1; speechSynthesis.speak(u); $('#voiceStatus').textContent='Model line playing. Stop when needed.';}catch(e){toast('Voice playback unavailable.')}}
async function startRecord(){if(!navigator.mediaDevices){toast('Recording not supported.');return} const stream=await navigator.mediaDevices.getUserMedia({audio:true}); recorder=new MediaRecorder(stream); recChunks=[]; recorder.ondataavailable=e=>recChunks.push(e.data); recorder.onstop=()=>{const blob=new Blob(recChunks,{type:'audio/webm'}); const reader=new FileReader(); reader.onload=()=>{state.recordings[p().n]=reader.result; save(); updateVoice(); toast('Local accent sample saved.');}; reader.readAsDataURL(blob); stream.getTracks().forEach(t=>t.stop());}; recorder.start(); $('#voiceStatus').textContent='Recording original/local accent sample...'}
function stopRecord(){if(recorder&&recorder.state==='recording'){recorder.stop(); $('#voiceStatus').textContent='Saving recording...'}}
function playRecorded(){const data=state.recordings[p().n]; if(!data){toast('No local accent recording saved for this province.');return} const a=new Audio(data); a.play(); $('#voiceStatus').textContent='Playing saved local accent recording.';}
function sendAI(){const q=$('#aiInput').value.trim(); if(!q)return; $('#chat').insertAdjacentHTML('beforeend',`<div class="info"><b>You:</b> ${q}</div>${aiAnswer(q)}`); $('#aiInput').value=''; $('#chat').scrollTop=$('#chat').scrollHeight;}
function saveStudioPNG(){const pr=p(); const txt=$('#workspace').textContent.trim()||'AKSANTARA'; const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1400" height="900"><rect width="100%" height="100%" fill="#061915"/><rect x="55" y="55" width="1290" height="790" rx="45" fill="#020b0d" stroke="#f8e894"/><text x="700" y="150" fill="#f8e894" font-size="58" text-anchor="middle" font-family="Georgia">${pr.name} — ${pr.aksara}</text><text x="700" y="450" fill="#fff4c8" font-size="110" text-anchor="middle" font-family="Georgia">${txt.replace(/[&<>]/g,'')}</text><text x="700" y="780" fill="#22ded1" font-size="30" text-anchor="middle" font-family="Arial">AKSANTARA © Dr. Joko Slamet</text></svg>`; downloadBlob(svg,'AKSANTARA-Studio.svg','image/svg+xml')}
function downloadBlob(data,name,type){const blob=new Blob([data],{type}); const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=name; a.click();}
function downloadQRCard(){const pr=p(); const c=document.createElement('canvas'); c.width=1200; c.height=1600; const ctx=c.getContext('2d'); const img=new Image(); img.onload=()=>{ctx.fillStyle='#061915'; ctx.fillRect(0,0,c.width,c.height); ctx.strokeStyle='#f8e894'; ctx.lineWidth=8; ctx.strokeRect(55,55,1090,1490); ctx.fillStyle='#f8e894'; ctx.font='bold 72px Georgia'; ctx.textAlign='center'; ctx.fillText('AKSANTARA',600,170); ctx.font='bold 36px Arial'; ctx.fillText(`${pr.name} • ${pr.aksara}`,600,245); ctx.fillStyle='#fff'; ctx.fillRect(330,315,540,540); ctx.drawImage(img,360,345,480,480); ctx.fillStyle='#f8e894'; ctx.font='bold 34px Arial'; wrap(ctx,`${pr.wisdom}. ${pr.story}. Voice focus: ${pr.focus}.`,600,930,820,48); c.toBlob(b=>{const a=document.createElement('a'); a.href=URL.createObjectURL(b); a.download=`AKSANTARA-QR-${pr.name}.png`; a.click();});}; img.src=`assets/qr/${String(pr.n).padStart(2,'0')}.png`;}
function wrap(ctx,text,x,y,maxWidth,lineHeight){let words=text.split(' '),line=''; for(const w of words){let test=line+w+' '; if(ctx.measureText(test).width>maxWidth){ctx.fillText(line,x,y); line=w+' '; y+=lineHeight;} else line=test;} ctx.fillText(line,x,y);}
function wire(){document.addEventListener('click',e=>{const goEl=e.target.closest('[data-go]'); if(goEl){go(goEl.dataset.go); return} const prov=e.target.closest('[data-prov]'); if(prov){setProvince(prov.dataset.prov); return} const fil=e.target.closest('.filter'); if(fil){state.region=fil.dataset.region; renderFilters(); renderCards(); return} const smp=e.target.closest('[data-sample]'); if(smp){applySample(+smp.dataset.sample); return} const sk=e.target.closest('[data-skill]'); if(sk){state.skill=sk.dataset.skill; updateSkills(); return} const ans=e.target.closest('[data-answer]'); if(ans){if(ans.dataset.answer==='1'){state.progress[p().n+'-'+state.skill]=true; save(); toast('Correct. Task completed.')}else toast('Try again.'); updateSkills(); return} const comp=e.target.closest('[data-complete]'); if(comp){state.progress[p().n+'-'+state.skill]=true; save(); updateSkills(); toast('Task saved.'); return} const prompt=e.target.closest('.prompt'); if(prompt){$('#aiInput').value=prompt.dataset.prompt; sendAI(); return} const rem=e.target.closest('[data-remove-material]'); if(rem){const pr=p(); state.materials[pr.n].splice(+rem.dataset.removeMaterial,1); save(); renderMaterials(); return}}); $('#menuBtn').onclick=()=>$('#nav').classList.toggle('open'); $('#search').oninput=renderCards; ['studioSelect','voiceSelect','qrSelect','adminSelect'].forEach(id=>{$('#'+id).onchange=e=>setProvince(e.target.value)}); $('#qrApply').onclick=()=>setProvince($('#qrSelect').value); $('#copyAllAksara').onclick=()=>{navigator.clipboard?.writeText(samples().map(s=>`${s.ch} — ${s.meaning}`).join('\n')); toast('All samples copied.')}; $('#copyWritten').onclick=()=>{navigator.clipboard?.writeText($('#workspace').textContent.trim()); toast('Written aksara copied.')}; $('#translateBtn').onclick=translateWorkspace; $('#clearStudio').onclick=()=>{$('#workspace').innerHTML=''; translateWorkspace();}; $('#saveStudio').onclick=saveStudioPNG; $('#playVoice').onclick=()=>speak(`${p().name} connects ${p().aksara} and ${p().wisdom} with intelligible English communication.`); $('#stopVoice').onclick=()=>{speechSynthesis.cancel(); $('#voiceStatus').textContent='Stopped.'}; $('#recordVoice').onclick=startRecord; $('#stopRecord').onclick=stopRecord; $('#playRecorded').onclick=playRecorded; $('#aiSend').onclick=sendAI; $('#aiInput').onkeydown=e=>{if(e.key==='Enter')sendAI()}; $('#downloadQR').onclick=downloadQRCard; $('#unlock').onclick=()=>{if($('#pin').value==='JS2026'){$('#adminBox').classList.remove('locked'); $('#adminStatus').textContent='Unlocked.'; toast('Admin unlocked.')}else toast('Incorrect PIN.')}; $('#lock').onclick=()=>{$('#adminBox').classList.add('locked'); $('#adminStatus').textContent='Locked.'}; $('#saveAdminContent').onclick=()=>{const pr=baseProv(); state.custom[pr.n]=Object.assign({},state.custom[pr.n]||{},{wisdom:$('#adminWisdom').value,story:$('#adminStory').value,focus:$('#adminFocus').value}); save(); updateAll(); toast('Province updated locally.')}; $('#addMaterial').onclick=()=>{const pr=p(); const title=$('#materialTitle').value.trim(), body=$('#materialBody').value.trim(); if(!title||!body){toast('Add title and content.');return} state.materials[pr.n]=state.materials[pr.n]||[]; state.materials[pr.n].push({title,body}); $('#materialTitle').value=''; $('#materialBody').value=''; save(); renderMaterials(); toast('Material added.')}; $('#addAksara').onclick=()=>{const pr=baseProv(), ch=$('#newAksara').value.trim(), meaning=$('#newMeaning').value.trim(); if(!ch||!meaning){toast('Add symbol and meaning.');return} const cur=state.custom[pr.n]||{}; cur.samples=cur.samples||p().samples.slice(); cur.samples.push({ch,meaning,en:`${pr.name} uses ${ch} to express ${meaning}.`,id:`${pr.name} menggunakan ${ch} untuk mengekspresikan ${meaning}.`}); state.custom[pr.n]=cur; $('#newAksara').value=''; $('#newMeaning').value=''; save(); updateAll(); toast('Aksara sample added.')}; $('#resetApp').onclick=()=>{state.progress={}; save(); updateAll(); toast('Progress reset.')}; $('#exportState').onclick=()=>downloadBlob(JSON.stringify(state,null,2),'aksantara-state.json','application/json'); $$('.board').forEach(b=>b.onclick=()=>{$('#modalImg').src=b.dataset.img; $('#modal').classList.add('open')}); $('#closeModal').onclick=()=>$('#modal').classList.remove('open'); window.addEventListener('resize',renderMap);}
load(); renderZones(); wire(); updateAll();
